void __stdcall AddCollision_Width(D2RoomStrc * pRoom, int32_t nX, int32_t nY, eD2CollisionUnitSize nWidth, int32_t eCollisionFlag) {
    D2BoundingBoxStrc sBox;
    switch (nWidth) {
      case COLLISION_UNIT_SIZE_POINT:
        {
          COLLISN_SetCellMask(pRoom, nX, nY, (eCollisionFlags)eCollisionFlag);
          break;
        }
      case COLLISION_UNIT_SIZE_SMALL:
        {
          AddCollision_Cross(pRoom, nX, nY, (eCollisionFlags)eCollisionFlag);
          return;
        }
      case COLLISION_UNIT_SIZE_BIG:
        {
          sBox.nLeft = nX - 1;
          sBox.nRight = nX + 1;
          sBox.nBottom = nY - 1;
          sBox.nTop = nY + 1;
          AddCollision_BoundingBox(pRoom, &sBox, eCollisionFlag);
          return;
        }
    }
}

// Applies eCollisionFlag to the collision grid at (nX,nY) using the shape specified by nType (eD2CollisionShapeType). Small shapes use AddCollision_Cross; big shapes use AddCollision_BoundingBox1. For unit/pet presence patterns also adds a secondary COLLIDE_UNIT_RELATED or COLLIDE_PET flag via AddCollision_Internal. Dispatches on COLLISION_PATTERN_* enum cases.
void __stdcall AddCollision_Type(D2RoomStrc * pRoom, int32_t nX, int32_t nY, eD2CollisionShapeType nType, int32_t eCollisionFlag) {
    eCollisionFlags eCollisionFlag_00 = (eCollisionFlags)eCollisionFlag;
    switch (nType) {
      case COLLISION_PATTERN_NONE:
        break;
      case COLLISION_PATTERN_SMALL_UNIT_PRESENCE:
        AddCollision_Cross(pRoom, nX, nY, eCollisionFlag_00);
      if (eCollisionFlag) {
        COLLISN_SetCellMask(pRoom, nX, nY, COLLIDE_UNIT_RELATED);
        return;
      }

      break;
      case COLLISION_PATTERN_BIG_UNIT_PRESENCE:
        AddCollision_BoundingBox1(pRoom, nX, nY, eCollisionFlag);
      if (eCollisionFlag) {
        AddCollision_Cross(pRoom, nX, nY, COLLIDE_UNIT_RELATED);
        return;
      }

      break;
      case COLLISION_PATTERN_SMALL_PET_PRESENCE:
        AddCollision_Cross(pRoom, nX, nY, eCollisionFlag_00);
      if (eCollisionFlag) {
        COLLISN_SetCellMask(pRoom, nX, nY, COLLIDE_PET);
        return;
      }

      break;
      case COLLISION_PATTERN_BIG_PET_PRESENCE:
        AddCollision_BoundingBox1(pRoom, nX, nY, eCollisionFlag);
      if (eCollisionFlag) {
        AddCollision_Cross(pRoom, nX, nY, COLLIDE_PET);
        return;
      }

      break;
      case COLLISION_PATTERN_SMALL_NO_PRESENCE:
        AddCollision_Cross(pRoom, nX, nY, eCollisionFlag_00);
      break;
      default:
        break;
    }
}

void __stdcall RemoveCollision_Width(D2RoomStrc * pRoom, int32_t nX, int32_t nY, eD2CollisionUnitSize nWidth, int32_t eCollisionFlag) {
    if (!pRoom) {
      return;
    }

    switch (nWidth) {
      case COLLISION_UNIT_SIZE_POINT:
        COLLISN_ClearCellMask(pRoom, nX, nY, (eCollisionFlags)eCollisionFlag);
      return;
      case COLLISION_UNIT_SIZE_SMALL:
        RemoveCollision_Cross(pRoom, nX, nY, eCollisionFlag);
      return;
      case COLLISION_UNIT_SIZE_BIG:
        RemoveCollision_BoundingBox1(pRoom, nX, nY, eCollisionFlag);
      case COLLISION_UNIT_SIZE_NONE:
        break;
    }
}

